CREATE FUNCTION cmd_reject_device_operation_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Device operation receipts are immutable'; END $$;
CREATE TRIGGER cmd_device_operation_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_device_operation_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_device_operation_mutation();
CREATE FUNCTION cmd_validate_device_operation_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; expected_skill bigint; BEGIN SELECT skill_rule_id INTO STRICT expected_skill FROM rule_device_operation WHERE rule_id=NEW.operation_rule_id AND operation_code=NEW.operation_code; SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>expected_skill OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Device operation receipt does not match its task'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_device_operation_receipt_valid AFTER INSERT ON cmd_device_operation_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_device_operation_receipt();
